query.expr:
pC -> {
  toUnitQty = value -> fromUnit -> toUnit -> {
    fromFactor =
      switch {
        // MASS
        $fromUnit == `luigis.pizzashop:UnitOfMeasure#G`      : 1;
        $fromUnit == `luigis.pizzashop:UnitOfMeasure#KG`     : 1000;
        $fromUnit == `luigis.pizzashop:UnitOfMeasure#T`      : 1000000;

        // VOLUME
        $fromUnit == `luigis.pizzashop:UnitOfMeasure#ML`     : 1;
        $fromUnit == `luigis.pizzashop:UnitOfMeasure#L`      : 1000;

        // TIME (base = MINUTE)
        $fromUnit == `luigis.pizzashop:UnitOfMeasure#MINUTE` : 1;
        $fromUnit == `luigis.pizzashop:UnitOfMeasure#HOUR`   : 60;

        true                                           : null;
      };

    toFactor =
      switch {
        // MASS
        $toUnit == `luigis.pizzashop:UnitOfMeasure#G`        : 1;
        $toUnit == `luigis.pizzashop:UnitOfMeasure#KG`       : 1000;
        $toUnit == `luigis.pizzashop:UnitOfMeasure#T`        : 1000000;

        // VOLUME
        $toUnit == `luigis.pizzashop:UnitOfMeasure#ML`       : 1;
        $toUnit == `luigis.pizzashop:UnitOfMeasure#L`        : 1000;

        // TIME (base = MINUTE)
        $toUnit == `luigis.pizzashop:UnitOfMeasure#MINUTE`   : 1;
        $toUnit == `luigis.pizzashop:UnitOfMeasure#HOUR`     : 60;

        true                                           : null;
      };

    result =
      switch {
        $fromUnit == $toUnit
          : $value;
        $fromFactor != null && $toFactor != null
          : $value * $fromFactor / $toFactor;
        true
          : null;
      };

    $result
  };
c          = $pC.get(`luigis.pizzashop:ProductComponent#component`);
  amount     = $pC.get(`luigis.pizzashop:ProductComponent#amount`);
  fromUnit   = $pC.get(`luigis.pizzashop:ProductComponent#unit`);
  baseUnit   = $c.get(`luigis.pizzashop:Component#baseUnit`);
  pricePerBU = $c.get(`luigis.pizzashop:Component#costPerBaseUnit`);
  qtyInBase  = $toUnitQty($amount, $fromUnit, $baseUnit);
  $qtyInBase * $pricePerBU


}
